-- Nama kampus & prodi Indonesia (PDDikti, ditarik Okt 2026; semester prodi 20251).
-- PostgreSQL. Aman dijalankan ulang: tabel/enum dibuat bila belum ada,
-- kampus di-upsert per npsn (= kode PT PDDikti), isi prodi diganti total.
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f nama_kampus_prodi.sql
BEGIN;
DO $$ BEGIN
  CREATE TYPE "KelompokKampus" AS ENUM ('PTK', 'PTA', 'PTN', 'PTS');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  CREATE TYPE "BadanPembina" AS ENUM ('SEKOLAH_TINGGI', 'POLITEKNIK', 'AKADEMI', 'INSTITUT', 'AKADEMI_KOMUNITAS', 'UNIVERSITAS');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "nama_kampus" (
    "id" SERIAL PRIMARY KEY,
    "nama" TEXT NOT NULL,
    "kelompok" "KelompokKampus",
    "npsn" TEXT NOT NULL,
    "namaBadan" "BadanPembina",
    "provinsi" TEXT NOT NULL,
    "kabupaten" TEXT NOT NULL,
    "aktif" BOOLEAN NOT NULL DEFAULT true
);
-- tabel versi lama (sebelum kolom aktif & entri manual)
ALTER TABLE nama_kampus ALTER COLUMN kelompok DROP NOT NULL, ALTER COLUMN "namaBadan" DROP NOT NULL;
ALTER TABLE nama_kampus ADD COLUMN IF NOT EXISTS aktif BOOLEAN NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS "prodi_kampus" (
    "id" SERIAL PRIMARY KEY,
    "kodePt" TEXT NOT NULL,
    "kodeProdi" TEXT NOT NULL,
    "nama" TEXT NOT NULL,
    "jenjang" TEXT NOT NULL,
    "status" TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "nama_kampus_npsn_key" ON "nama_kampus"("npsn");
CREATE INDEX IF NOT EXISTS "nama_kampus_nama_kabupaten_idx" ON "nama_kampus"("nama", "kabupaten");
CREATE UNIQUE INDEX IF NOT EXISTS "prodi_kampus_kodePt_jenjang_nama_key" ON "prodi_kampus"("kodePt", "jenjang", "nama");

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

TRUNCATE prodi_kampus RESTART IDENTITY;
