-- Entri manual: tidak ada di PDDikti tapi banyak dipakai alumni (npsn berawalan X)
ON CONFLICT (npsn) DO UPDATE SET nama=EXCLUDED.nama, kelompok=EXCLUDED.kelompok, "namaBadan"=EXCLUDED."namaBadan", provinsi=EXCLUDED.provinsi, kabupaten=EXCLUDED.kabupaten;

-- PT lama yang sudah alih bentuk disembunyikan dari pencarian.
-- ponytail: tebakan dari status prodi PDDikti; PT tanpa data prodi dianggap aktif. Salah tebak -> UPDATE manual per npsn.
UPDATE nama_kampus k SET aktif = COALESCE((
  SELECT count(*) FILTER (WHERE status IN ('Aktif','Pembinaan')) > count(*) FILTER (WHERE status='Alih Bentuk')
  FROM prodi_kampus p WHERE p."kodePt"=k.npsn HAVING count(*)>0), true);
-- IAIN/STAIN yang sudah jadi UIN/IAIN tapi PDDikti masih menyisakan prodi Aktif di kode lama (IAIN Imam Bonjol, ...)
UPDATE nama_kampus k SET aktif = false
WHERE aktif AND nama ~ '^(IAIN|STAIN|Institut Agama Islam Negeri|Sekolah Tinggi Agama Islam Negeri)'
  AND EXISTS (SELECT 1 FROM prodi_kampus p WHERE p."kodePt"=k.npsn AND status='Alih Bentuk');
-- ... atau penerusnya (UIN untuk IAIN; UIN/IAIN untuk STAIN) ada di kabupaten yang sama (IAIN Raden Fatah, STAIN Sorong, ...)
UPDATE nama_kampus k SET aktif = false
WHERE aktif AND nama ~ '^(IAIN |STAIN |Institut Agama Islam Negeri |Sekolah Tinggi Agama Islam Negeri )'
  AND EXISTS (SELECT 1 FROM nama_kampus u WHERE u.aktif AND u.npsn <> k.npsn AND u.kabupaten = k.kabupaten
    AND u.nama ~ CASE WHEN k.nama ~ '^(IAIN|Institut)' THEN '^Universitas Islam Negeri ' ELSE '^(Universitas Islam Negeri |Institut Agama Islam Negeri |IAIN )' END);

COMMIT;
